mapper.select:
select warehouse_id
from `ry_rental`.`ry_rental_user_warehouse_scope`
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and merchant_user_id = #{merchantUserId}
  and is_delete = 0
order by warehouse_id

mapper.update:
update `ry_rental`.`ry_rental_user_warehouse_scope` set is_delete = 1 where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and merchant_user_id = #{merchantUserId}
